diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..d7ca9b7aa
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,18 @@
+// Usage (from repo root): node repro/check.js [file.ts]
+// Asserts the expected behavior from the report: the type of `Test` is displayed as `{ prop1: "hello"; }`.
+// TS_MODULE can point at another typescript.js (e.g. a published 5.6.3) to run the same check there.
+const path = require("path");
+const ts = require(process.env.TS_MODULE || path.resolve("built/local/typescript.js"));
+const file = path.resolve(process.argv[2] || "repro/report.ts");
+const program = ts.createProgram([file], { strict: true, noEmit: true, types: [], lib: ["lib.es2022.d.ts"], target: ts.ScriptTarget.ES2022 });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+const alias = sf.statements.find(s => ts.isTypeAliasDeclaration(s) && s.name.text === "Test");
+const actual = checker.typeToString(checker.getTypeAtLocation(alias.name), undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias);
+const expected = '{ prop1: "hello"; }';
+console.log(`TypeScript ${ts.version}: Test = ${actual}`);
+if (actual !== expected) {
+    console.error(`FAIL: expected Test = ${expected}`);
+    process.exit(1);
+}
+console.log("OK");
diff --git a/repro/report.ts b/repro/report.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/report.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
diff --git a/repro/separate.ts b/repro/separate.ts
new file mode 100644
index 000000000..8ded11194
--- /dev/null
+++ b/repro/separate.ts
@@ -0,0 +1,9 @@
+type Wrapper<T> = { _type: T }
+function stringWrapper(): Wrapper<string> { return { _type: "" } }
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> { return { _type: obj } }
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+const value = objWrapper({ prop1: strWrapper });
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+type Test = Unwrap<typeof value>
